const msg = $json.body.message;
const tc = msg.toolCallList[0];
let args = tc.arguments || (tc.function && tc.function.arguments) || {};
if (typeof args === 'string') args = JSON.parse(args);
return [{
  json: {
    toolCallId: tc.id,
    toolName: tc.name || (tc.function && tc.function.name),
    args: args,
    callerNumber: (msg.call && msg.call.customer && msg.call.customer.number) || null,
    callId: (msg.call && msg.call.id) || null
  }
}];

const info = $('Parse Tool Call').first().json;
const rows = $input.all().map(i => i.json.fields || i.json).filter(r => r.party_size);
const booked = rows.reduce((sum, r) => sum + Number(r.party_size), 0);
const CAPACITY = 40;
const left = CAPACITY - booked;
const wanted = Number(info.args.party_size);
const text = left >= wanted
  ? `Yes, there is space for ${wanted} people on ${info.args.date} at ${info.args.time}.`
  : `That time is fully booked, only ${left} seats left. Offer the caller a different time.`;
return [{ json: { results: [{ toolCallId: info.toolCallId, result: text }] } }];

const info = $json;
const a = info.args;
const code = 'SRK-' + Math.floor(1000 + Math.random() * 9000);
return [{
  json: {
    toolCallId: info.toolCallId,
    code: code,
    row: {
      confirmation_code: code,
      customer_name: a.customer_name,
      phone: a.phone || info.callerNumber,
      party_size: a.party_size,
      reservation_date: a.date,
      reservation_time: a.time,
      notes: a.notes || null,
      call_id: info.callId
    }
  }
}];

const MENU = {
  'jollof rice with grilled chicken': 6500,
  'ofada rice with ayamase': 7500,
  'egusi soup with pounded yam': 7000,
  'suya platter': 8500,
  'peppered asun': 5500,
  'fried plantain': 2000,
  'moi moi': 1500,
  'puff puff': 2000,
  'chapman': 2500,
  'zobo': 1500
};
const info = $json;
const a = info.args;
let total = 0;
const lines = [];
const unknown = [];
for (const it of (a.items || [])) {
  const key = String(it.name).toLowerCase().trim();
  const qty = Number(it.quantity || 1);
  if (MENU[key] === undefined) { unknown.push(it.name); continue; }
  total += MENU[key] * qty;
  lines.push(`${qty}x ${it.name}`);
}
const code = 'ORD-' + Math.floor(1000 + Math.random() * 9000);
return [{
  json: {
    toolCallId: info.toolCallId,
    unknown: unknown,
    code: code,
    total: total,
    orderType: a.order_type,
    row: {
      order_code: code,
      customer_name: a.customer_name,
      phone: a.phone || info.callerNumber,
      order_type: a.order_type,
      delivery_address: a.delivery_address || null,
      items: lines.join(', '),
      total_amount: total,
      call_id: info.callId
    }
  }
}];

const prep = $('Prep Order').first().json;
const wait = prep.orderType === 'delivery' ? 'about 45 to 60 minutes' : 'about 30 minutes';
return [{ json: { results: [{ toolCallId: prep.toolCallId, result: `Order saved. The order number is ${prep.code}. The total is ${prep.total} naira. It will be ready in ${wait}.` }] } }];

const m = $json.body.message;
return [{
  json: {
    row: {
      call_id: (m.call && m.call.id) || null,
      caller_number: (m.call && m.call.customer && m.call.customer.number) || null,
      duration_seconds: Math.round(m.durationSeconds || 0),
      summary: (m.analysis && m.analysis.summary) || m.summary || null,
      transcript: (m.artifact && m.artifact.transcript) || m.transcript || null,
      ended_reason: m.endedReason || null,
      cost: m.cost || null
    }
  }
}];
